import numpy as np

def f(p):    return p[0]**2 + 3*p[1]**2
def grad(p): return np.array([2*p[0], 6*p[1]])

for eta in [0.05, 0.1, 0.2, 0.3, 0.35]:
    p = np.array([2.0, 1.0])
    for k in range(10):
        p = p - eta * grad(p)          # the gradient descent update
    print(f"eta={eta}: loss after 10 steps = {f(p):.4g}")
